// CUDA WebShader 0.1.1. Generated from kernel scene_style_stats.
@group(0) @binding(0) var<storage, read> b_pixels: array<u32>;
@group(0) @binding(1) var<storage, read> b_picks: array<u32>;
@group(0) @binding(2) var<storage, read_write> b_stats: array<atomic<u32>>;
struct CWParams {
  p_w: i32,
  p_h: i32,
  cw_pad_8: u32,
  cw_pad_12: u32,
}
@group(0) @binding(3) var<uniform> cw_params: CWParams;
const cw_block_size: vec3<u32> = vec3<u32>(128u, 1u, 1u);



alias cw_f64 = vec2<u32>;










struct CWDoubleParts { significand: vec2<u32>, exponent: i32, }

// Input has its leading bit at bit 55 and three guard/round/sticky bits.














// Restoring square root: 56 root bits include guard/round/sticky for binary64.














































@compute @workgroup_size(128, 1, 1)
fn main(
  @builtin(local_invocation_id) cw_thread: vec3<u32>,
  @builtin(workgroup_id) cw_block: vec3<u32>,
  @builtin(num_workgroups) cw_grid: vec3<u32>
) {
  var v_i: u32 = ((cw_block.x * cw_block_size.x) + cw_thread.x);
  if ((v_i >= u32((cw_params.p_w * cw_params.p_h)))) {
    return;
  }
  var v_id: u32 = b_picks[v_i];
  if ((v_id == 0u)) {
    return;
  }
  var v_k: u32 = (v_id * 8u);
  var v_x: u32 = (v_i % u32(cw_params.p_w));
  var v_y: u32 = (v_i / u32(cw_params.p_w));
  if (((v_x == 0u) || (b_picks[(v_i - 1u)] != v_id))) {
    _ = atomicMin(&b_stats[v_k], v_x);
  }
  if (((v_x == u32((cw_params.p_w - 1i))) || (b_picks[(v_i + 1u)] != v_id))) {
    _ = atomicMax(&b_stats[(v_k + 2u)], v_x);
  }
  if (((v_y == 0u) || (b_picks[(v_i - u32(cw_params.p_w))] != v_id))) {
    _ = atomicMin(&b_stats[(v_k + 1u)], v_y);
  }
  if (((v_y == u32((cw_params.p_h - 1i))) || (b_picks[(v_i + u32(cw_params.p_w))] != v_id))) {
    _ = atomicMax(&b_stats[(v_k + 3u)], v_y);
  }
}
